INSERT INTO roles(code,name) VALUES ('SUPER_ADMIN','Super Admin'),('PROJECT_ADMIN','Project Admin'),('STATE_COORDINATOR','State Coordinator'),('FACILITATOR','Facilitator'),('GROUP_OFFICER','Group Officer'),('MEMBER','Member') ON CONFLICT(code) DO NOTHING;
INSERT INTO permissions(code) SELECT unnest(ARRAY['organization.view','organization.manage','project.create','project.view','project.update','project.archive','user.create','user.view','user.update','user.disable','facilitator.create','facilitator.view','facilitator.update','group.create','group.view','group.update','group.activate','member.create','member.view','member.update','constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage','meeting.create','meeting.view','meeting.manage','savings.view','savings.record','loan.view','loan.request','loan.approve','loan.disburse','loan.repay','social_fund.view','social_fund.record','social_fund.approve','shareout.view','shareout.execute','report.view','report.export','audit.view']) ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='PROJECT_ADMIN' AND p.code IN ('project.view','project.update','user.create','user.view','user.update','facilitator.create','facilitator.view','facilitator.update','group.create','group.view','group.update','group.activate','member.create','member.view','member.update','constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage','report.view') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='STATE_COORDINATOR' AND p.code IN ('project.view','user.view','facilitator.view','facilitator.update','group.create','group.view','group.update','group.activate','member.create','member.view','member.update','constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage','report.view') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='FACILITATOR' AND p.code IN ('project.view','group.view','group.update','member.create','member.view','member.update','constitution.view','constitution.manage','cycle.view','cycle.manage','officer.view','officer.manage','meeting.create','meeting.view','meeting.manage','savings.view','savings.record','loan.view','loan.request','loan.repay','social_fund.view','social_fund.record') ON CONFLICT DO NOTHING;
